DROP TABLE IF EXISTS `alunoview`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `alunoview`  AS SELECT `su`.`id` AS `id`, `su`.`name` AS `name`, `su`.`login` AS `login`, `su`.`email` AS `email`, `su`.`active` AS `active`, `t`.`id` AS `id_turma`, `t`.`identificacao` AS `turma` FROM ((((`system_user` `su` join `aluno_escola` `ae` on(`su`.`id` = `ae`.`id_aluno`)) left join `system_user_group` `sug` on(`su`.`id` = `sug`.`system_user_id`)) left join `turma_aluno` `ta` on(`su`.`id` = `ta`.`id_aluno`)) left join `turma` `t` on(`ta`.`id_turma` = `t`.`id`)) WHERE `sug`.`system_group_id` = 4 AND `ae`.`id_escola` = 100 ;

