--
-- Estrutura para view `vw_analise_capacidade`
--
DROP TABLE IF EXISTS `vw_analise_capacidade`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_analise_capacidade`  AS SELECT `t1`.`escola` AS `escola`, `t1`.`turma` AS `turma`, `t1`.`login` AS `login`, `t1`.`jogador` AS `jogador`, max(`t1`.`dt_jogo`) AS `dt_jogo`, `t1`.`idade` AS `idade`, `t1`.`auto_avaliacao` AS `auto_avaliacao`, `t1`.`avaliacao_jogo` AS `avaliacao_jogo`, `t1`.`tutor` AS `tutor`, `t1`.`categoria` AS `categoria`, `t1`.`tema` AS `tema`, `t1`.`numero_partidas` AS `numero_partidas`, `t1`.`tempo_gasto` AS `tempo_gasto`, `t1`.`tempo_leitura_adulto` AS `tempo_leitura_adulto`, `t1`.`tempo_leitura_infantil` AS `tempo_leitura_infantil`, `t1`.`percentual_acertos` AS `percentual_acertos`, `t1`.`percentual_erros` AS `percentual_erros`, max(case when `t1`.`tipo_partida` = 'PARTIDA INICIAL' then `t1`.`percentual_acertos` end) AS `partida_inicial`, max(case when `t1`.`tipo_partida` = 'PARTIDA FINAL' then `t1`.`percentual_acertos` end) AS `partida_final` FROM (select `p`.`escola` AS `escola`,`p`.`turma` AS `turma`,`p`.`login` AS `login`,`p`.`jogador` AS `jogador`,`p`.`partida` AS `partida`,`p`.`dt_jogo` AS `dt_jogo`,`p`.`idade` AS `idade`,`p`.`auto_avaliacao` AS `auto_avaliacao`,`p`.`avaliacao_jogo` AS `avaliacao_jogo`,`p`.`tutor` AS `tutor`,`p`.`categoria` AS `categoria`,`p`.`tema` AS `tema`,`p`.`numero_partidas` AS `numero_partidas`,`p`.`tempo_gasto` AS `tempo_gasto`,`p`.`tempo_leitura_adulto` AS `tempo_leitura_adulto`,`p`.`tempo_leitura_infantil` AS `tempo_leitura_infantil`,`p`.`percentual_acertos` AS `percentual_acertos`,`p`.`percentual_erros` AS `percentual_erros`,`p`.`finalizada` AS `finalizada`,`p`.`tipo_partida` AS `tipo_partida` from `vw_partidas` `p` where `p`.`tipo_partida` in ('PARTIDA INICIAL','PARTIDA FINAL') and `p`.`numero_partidas` > 1) AS `t1` GROUP BY `t1`.`login`, `t1`.`jogador` ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_apriori`
--
DROP TABLE IF EXISTS `vw_apriori`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_apriori`  AS SELECT row_number() over ( order by `t1`.`escola`,`t1`.`turma`,`t1`.`login`,`t1`.`jogador`,`t1`.`dt_jogo`) AS `id`, `t1`.`escola` AS `escola`, `t1`.`turma` AS `turma`, `t1`.`login` AS `login`, `t1`.`jogador` AS `jogador`, `t1`.`dt_jogo` AS `dt_jogo`, `t1`.`idade` AS `idade`, `t1`.`auto_avaliacao` AS `auto_avaliacao`, `t1`.`avaliacao_jogo` AS `avaliacao_jogo`, `t1`.`tutor` AS `tutor`, `t1`.`categoria` AS `categoria`, `t1`.`tema` AS `tema`, `t1`.`numero_partidas` AS `numero_partidas`, `t1`.`tempo_gasto` AS `tempo_gasto`, `t1`.`tempo_leitura_adulto` AS `tempo_leitura_adulto`, `t1`.`tempo_leitura_infantil` AS `tempo_leitura_infantil`, `t1`.`percentual_acertos` AS `percentual_acertos`, `t1`.`percentual_erros` AS `percentual_erros`, CASE WHEN `t1`.`partida_inicial` > `t1`.`partida_final` THEN 'DIMINUIU' WHEN `t1`.`partida_inicial` = `t1`.`partida_final` THEN 'MANTEVE' WHEN `t1`.`partida_inicial` < `t1`.`partida_final` THEN 'AUMENTOU' END AS `capacidade_critica` FROM `vw_analise_capacidade` AS `t1` ORDER BY `t1`.`login` ASC, `t1`.`jogador` ASC, `t1`.`dt_jogo` ASC, `t1`.`escola` ASC, `t1`.`turma` ASC ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_caracteristicas_textuais_noticia`
--
DROP TABLE IF EXISTS `vw_caracteristicas_textuais_noticia`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_caracteristicas_textuais_noticia`  AS SELECT row_number() over ( order by `t`.`caracteristica_observada`) AS `id`, `t`.`caracteristica_observada` AS `caracteristica_observada`, `t`.`fake` AS `fake`, `t`.`nao_fake` AS `nao_fake` FROM (select 'Número de caracteres por artigo de notícias' AS `caracteristica_observada`,concat(round(avg(case when `p`.`resp_certa` = 'FAKE' then `p`.`numero_caracteres` end),2),' ± ',round(std(case when `p`.`resp_certa` = 'FAKE' then `p`.`numero_caracteres` end),2)) AS `fake`,concat(round(avg(case when `p`.`resp_certa` = 'NÃO FAKE' then `p`.`numero_caracteres` end),2),' ± ',round(std(case when `p`.`resp_certa` = 'NÃO FAKE' then `p`.`numero_caracteres` end),2)) AS `nao_fake` from `pergunta` `p` where `p`.`resp_certa` in ('FAKE','NÃO FAKE') union all select 'Número de palavras por artigo de notícias' AS `caracteristica_observada`,concat(round(avg(case when `p`.`resp_certa` = 'FAKE' then `p`.`numero_palavras` end),2),' ± ',round(std(case when `p`.`resp_certa` = 'FAKE' then `p`.`numero_palavras` end),2)) AS `fake`,concat(round(avg(case when `p`.`resp_certa` = 'NÃO FAKE' then `p`.`numero_palavras` end),2),' ± ',round(std(case when `p`.`resp_certa` = 'NÃO FAKE' then `p`.`numero_palavras` end),2)) AS `nao_fake` from `pergunta` `p` where `p`.`resp_certa` in ('FAKE','NÃO FAKE')) AS `t` ;

-- --------------------------------------------------------

