DROP TABLE IF EXISTS `vw_dados_analiticos`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_dados_analiticos`  AS SELECT `su`.`id` AS `id_usuario`, `su`.`name` AS `nome_usuario`, `su`.`login` AS `login_usuario`, `su`.`email` AS `email_usuario`, `su`.`active` AS `status_usuario`, `e`.`nome` AS `nome_escola`, `e`.`num_alunos` AS `num_alunos_escola`, `e`.`num_profs` AS `num_professores_escola`, `e`.`zona_localizacao` AS `zona_localizacao_escola`, `m`.`nome` AS `nome_municipio`, `m`.`num_habitantes` AS `num_habitantes_municipio`, `m`.`idh` AS `idh_municipio`, `m`.`renda_media` AS `renda_media_municipio`, `ig`.`nome` AS `nome_instancia_gestora`, `t`.`identificacao` AS `identificacao_turma`, `t`.`ano` AS `ano_turma`, `se`.`descricao` AS `nome_serie_escolar`, `ne`.`descricao` AS `nome_nivel_ensino`, `pp`.`id` AS `id_partida`, `pp`.`dt_jogo` AS `dt_jogo_partida`, `pp`.`tutor` AS `tutor_partida`, `pp`.`jogador` AS `jogador_partida`, `pp`.`pontuacao` AS `pontuacao_partida`, `pp`.`qtd_acertos` AS `qtd_acertos_partida`, `pp`.`qtd_erros` AS `qtd_erros_partida`, `pp`.`tempo_gasto` AS `tempo_gasto_partida`, `pp`.`auto_avaliacao` AS `auto_avaliacao_partida`, `pp`.`avaliacao_jogo` AS `avaliacao_jogo_partida`, `pp`.`idade` AS `idade_jogador_partida`, `pp`.`finalizado` AS `partida_finalizada`, `lp`.`num_jogada` AS `num_jogada_log_pergunta`, `lp`.`resp_dada` AS `resp_dada_log_pergunta`, `lp`.`posicao` AS `posicao_log_pergunta`, `lp`.`realizada_tutor` AS `realizada_tutor_log_pergunta`, `lp`.`tempo_gasto` AS `tempo_gasto_log_pergunta`, `p`.`id` AS `id_pergunta`, `p`.`pergunta` AS `pergunta`, `p`.`numero_caracteres` AS `num_caracteres_pergunta`, `p`.`numero_palavras` AS `num_palavras_pergunta`, `p`.`resp_certa` AS `resp_certa_pergunta`, `p`.`resp_2` AS `resp_2_pergunta`, `p`.`tempo_leitura_adulto` AS `tempo_leitura_adulto_pergunta`, `p`.`tempo_leitura_infantil` AS `tempo_leitura_infantil_pergunta`, `c`.`descricao` AS `categoria_pergunta`, `t2`.`nome` AS `tema`, `t2`.`visibilidade` AS `visibilidade`, `a`.`descricao` AS `nome_area` FROM ((((((((((((((((`system_user` `su` join `usuario_escola` `ue` on(`su`.`id` = `ue`.`id_usuario`)) join `escola` `e` on(`ue`.`id_escola` = `e`.`id`)) join `municipio` `m` on(`e`.`id_municipio` = `m`.`id`)) join `usuario_instancia_gestora` `uig` on(`su`.`id` = `uig`.`id_usuario`)) join `instancia_gestora` `ig` on(`uig`.`id_instancia_gestora` = `ig`.`id`)) join `turma` `t` on(`e`.`id` = `t`.`id_escola`)) join `serie_escolar` `se` on(`t`.`id_serie_escolar` = `se`.`id`)) join `nivel_ensino` `ne` on(`se`.`id_nivel_ensino` = `ne`.`id`)) join `turma_aluno` `ta` on(`t`.`id` = `ta`.`id_turma`)) join `partidas_perguntas` `pp` on(`su`.`id` = `pp`.`id_usuario`)) join `log_perguntas` `lp` on(`pp`.`id` = `lp`.`id_partida`)) join `pergunta_categoria` `pc` on(`lp`.`id_pergunta` = `pc`.`id_pergunta`)) join `pergunta` `p` on(`pc`.`id_pergunta` = `p`.`id`)) join `categoria` `c` on(`pc`.`id_categoria` = `c`.`id`)) join `tema` `t2` on(`pc`.`id_tema` = `t2`.`id`)) join `area2` `a` on(`t2`.`id_area` = `a`.`id`)) WHERE `su`.`active` = 'Y' ;

