CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_desempenho`  AS WITH desempenho_ind AS (SELECT `vr`.`escola` AS `escola`, `vr`.`turma` AS `turma`, `vr`.`login` AS `login`, `vr`.`jogador` AS `jogador`, `vr`.`partida` AS `partida`, `vr`.`dt_jogo` AS `dt_jogo`, `vr`.`idade` AS `idade`, `vr`.`auto_avaliacao` AS `auto_avaliacao`, `vr`.`avaliacao_jogo` AS `avaliacao_jogo`, `vr`.`tutor` AS `tutor`, `vr`.`pergunta_id` AS `pergunta_id`, `vr`.`tema` AS `tema`, `vr`.`finalizada` AS `finalizada`, group_concat(distinct `vr`.`categoria` separator ' / ') AS `categoria`, max(`vr`.`tempo_gasto`) AS `tempo_gasto`, max(`vr`.`tempo_leitura_adulto`) AS `tempo_leitura_adulto`, max(`vr`.`tempo_leitura_infantil`) AS `tempo_leitura_infantil`, sum(distinct `vr`.`acerto`) AS `numero_acertos`, sum(distinct `vr`.`erro`) AS `numero_erros` FROM `vw_respostas` AS `vr` GROUP BY `vr`.`escola`, `vr`.`turma`, `vr`.`login`, `vr`.`jogador`, `vr`.`partida`, `vr`.`pergunta_id` HAVING count(`vr`.`pergunta_id`) >= 1) SELECT `des`.`escola` AS `escola`, `des`.`turma` AS `turma`, `des`.`login` AS `login`, `des`.`jogador` AS `jogador`, `des`.`partida` AS `partida`, `des`.`dt_jogo` AS `dt_jogo`, `des`.`idade` AS `idade`, `des`.`auto_avaliacao` AS `auto_avaliacao`, `des`.`avaliacao_jogo` AS `avaliacao_jogo`, `des`.`tutor` AS `tutor`, `des`.`tema` AS `tema`, `des`.`finalizada` AS `finalizada`, group_concat(distinct `des`.`categoria` separator ' / ') AS `categoria`, (select count(distinct `d`.`partida`) from `desempenho_ind` `d` where `d`.`jogador` = `des`.`jogador`) AS `numero_partidas`, count(distinct `des`.`pergunta_id`) AS `numero_perguntas`, sum(`des`.`tempo_gasto`) AS `tempo_gasto`, sum(`des`.`tempo_leitura_adulto`) AS `tempo_leitura_adulto`, sum(`des`.`tempo_leitura_infantil`) AS `tempo_leitura_infantil`, sum(`des`.`numero_acertos`) AS `numero_acertos`, sum(`des`.`numero_erros`) AS `numero_erros`, round(sum(`des`.`numero_acertos`) / count(distinct `des`.`pergunta_id`) * 100,2) AS `percentual_acertos`, round(sum(`des`.`numero_erros`) / count(distinct `des`.`pergunta_id`) * 100,2) AS `percentual_erros` FROM `desempenho_ind` AS `des` GROUP BY `des`.`escola`, `des`.`turma`, `des`.`login`, `des`.`jogador`, `des`.`partida``partida`  ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_distribuicao_noticias_categoria`
--
DROP TABLE IF EXISTS `vw_distribuicao_noticias_categoria`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_distribuicao_noticias_categoria`  AS SELECT row_number() over ( order by `t`.`categoria`) AS `id`, `t`.`categoria` AS `categoria`, ifnull(max(case when `t`.`tipo_resposta` = 'FAKE' then `t`.`total_categoria` end),0) AS `fake_qt`, ifnull(round(100 * max(case when `t`.`tipo_resposta` = 'FAKE' then `t`.`total_categoria` end) / max(case when `t`.`tipo_resposta` = 'FAKE' then `t`.`total_geral` end),2),0) AS `fake_perc`, ifnull(max(case when `t`.`tipo_resposta` = 'NÃO FAKE' then `t`.`total_categoria` end),0) AS `nao_fake_qt`, ifnull(round(100 * max(case when `t`.`tipo_resposta` = 'NÃO FAKE' then `t`.`total_categoria` end) / max(case when `t`.`tipo_resposta` = 'NÃO FAKE' then `t`.`total_geral` end),2),0) AS `nao_fake_perc` FROM (select `c`.`descricao` AS `categoria`,'FAKE' AS `tipo_resposta`,ifnull(count(`p`.`id`),0) AS `total_categoria`,(select count(`p`.`id`) from ((`pergunta` `p` join `pergunta_categoria` `pc` on(`p`.`id` = `pc`.`id_pergunta`)) join `categoria` `c` on(`pc`.`id_categoria` = `c`.`id`)) where `p`.`resp_certa` = 'FAKE' and `c`.`descricao` is not null and `c`.`descricao` <> ' ') AS `total_geral` from ((`pergunta` `p` join `pergunta_categoria` `pc` on(`p`.`id` = `pc`.`id_pergunta`)) join `categoria` `c` on(`pc`.`id_categoria` = `c`.`id`)) where `p`.`resp_certa` = 'FAKE' and `c`.`descricao` is not null and `c`.`descricao` <> ' ' group by `c`.`descricao` union select `c`.`descricao` AS `categoria`,'NÃO FAKE' AS `tipo_resposta`,ifnull(count(`p`.`id`),0) AS `total_categoria`,(select count(`p`.`id`) from ((`pergunta` `p` join `pergunta_categoria` `pc` on(`p`.`id` = `pc`.`id_pergunta`)) join `categoria` `c` on(`pc`.`id_categoria` = `c`.`id`)) where `p`.`resp_certa` = 'NÃO FAKE' and `c`.`descricao` is not null and `c`.`descricao` <> ' ') AS `total_fake_geral` from ((`pergunta` `p` join `pergunta_categoria` `pc` on(`p`.`id` = `pc`.`id_pergunta`)) join `categoria` `c` on(`pc`.`id_categoria` = `c`.`id`)) where `p`.`resp_certa` = 'NÃO FAKE' and `c`.`descricao` is not null and `c`.`descricao` <> ' ' group by `c`.`descricao` order by `tipo_resposta`,`categoria`) AS `t` GROUP BY `t`.`categoria` ORDER BY row_number() over ( order by `t`.`categoria`) ASC ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_estatistica_avaliacoes`
--
DROP TABLE IF EXISTS `vw_estatistica_avaliacoes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_estatistica_avaliacoes`  AS WITH estatistica_avaliacoes AS (SELECT 'Avaliação do Jogo' AS `tipo`, `va`.`escola` AS `escola`, `va`.`turma` AS `turma`, `va`.`avaliacao_jogo` AS `avaliacao`, CASE `va`.`avaliacao_jogo` WHEN 'Proplayer' THEN 1 WHEN 'Avançado' THEN 2 WHEN 'Casual' THEN 3 WHEN 'Iniciante' THEN 4 WHEN 'Noob' THEN 5 END AS `ordem`, avg(`va`.`percentual_acertos`) AS `acerto` FROM `vw_apriori` AS `va` WHERE `va`.`avaliacao_jogo` not in ('Em processo','Não Preenchido','Meu nível para') GROUP BY `va`.`escola`, `va`.`turma`, `va`.`avaliacao_jogo`, CASE `va`.`avaliacao_jogo` WHEN 'Proplayer' THEN 1 WHEN 'Avançado' THEN 2 WHEN 'Casual' THEN 3 WHEN 'Iniciante' THEN 4 WHEN 'Noob' THEN 5 END UNION ALL SELECT 'Autoavaliação' AS `tipo`, `va`.`escola` AS `escola`, `va`.`turma` AS `turma`, `va`.`auto_avaliacao` AS `avaliacao`, CASE `va`.`auto_avaliacao` WHEN 'Proplayer' THEN 1 WHEN 'Avançado' THEN 2 WHEN 'Casual' THEN 3 WHEN 'Iniciante' THEN 4 WHEN 'Noob' THEN 5 END AS `ordem`, avg(`va`.`percentual_acertos`) AS `acerto` FROM `vw_apriori` AS `va` WHERE `va`.`auto_avaliacao` not in ('Em processo','Não Preenchido','Meu nível para') GROUP BY `va`.`escola`, `va`.`turma`, `va`.`auto_avaliacao`, CASE `va`.`auto_avaliacao` WHEN 'Proplayer' THEN 1 WHEN 'Avançado' THEN 2 WHEN 'Casual' THEN 3 WHEN 'Iniciante' THEN 4 WHEN 'Noob' THEN 5 END)  SELECT row_number() over ( order by `ea`.`escola`,`ea`.`turma`,`ea`.`ordem`) AS `id`, `ea`.`escola` AS `escola`, `ea`.`turma` AS `turma`, `ea`.`avaliacao` AS `avaliacao`, ifnull(sum(case when `ea`.`tipo` = 'Autoavaliação' then `ea`.`acerto` end),0) AS `autoavaliacao`, ifnull(sum(case when `ea`.`tipo` = 'Avaliação do Jogo' then `ea`.`acerto` end),0) AS `avaliacao_jogo` FROM `estatistica_avaliacoes` AS `ea` GROUP BY `ea`.`escola`, `ea`.`turma`, `ea`.`avaliacao`, `ea`.`ordem` ORDER BY `ea`.`escola` ASC, `ea`.`turma` ASC, `ea`.`ordem` ASC`ordem`  ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_estatistica_categoria_turma`
--
DROP TABLE IF EXISTS `vw_estatistica_categoria_turma`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_estatistica_categoria_turma`  AS SELECT row_number() over ( order by `p`.`escola`,`p`.`turma`,`p`.`categoria`,avg(`p`.`percentual_acertos`) desc) AS `id`, `p`.`escola` AS `escola`, `p`.`turma` AS `turma`, `p`.`categoria` AS `categoria`, avg(`p`.`percentual_acertos`) AS `media_acertos`, avg(`p`.`percentual_erros`) AS `media_erros` FROM `vw_partidas` AS `p` WHERE `p`.`categoria` is not null AND `p`.`categoria` <> '' GROUP BY `p`.`escola`, `p`.`turma`, `p`.`categoria` ORDER BY `p`.`escola` ASC, `p`.`turma` ASC, `p`.`categoria` ASC, avg(`p`.`percentual_acertos`) DESC ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_estatistica_partida_turma`
--
DROP TABLE IF EXISTS `vw_estatistica_partida_turma`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_estatistica_partida_turma`  AS SELECT row_number() over ( order by `ac`.`escola`,`ac`.`turma`) AS `id`, `ac`.`escola` AS `escola`, `ac`.`turma` AS `turma`, avg(`ac`.`partida_inicial`) AS `PI`, avg(`ac`.`partida_final`) AS `PF` FROM `vw_analise_capacidade` AS `ac` GROUP BY `ac`.`escola`, `ac`.`turma` ORDER BY `ac`.`escola` ASC, `ac`.`turma` ASC ;

