--
-- Estrutura para view `vw_intervalo_categorias`
--
DROP TABLE IF EXISTS `vw_intervalo_categorias`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_intervalo_categorias`  AS SELECT `t`.`avaliacao` AS `Categoria`, `t`.`faixa` AS `Faixa de Acertos` FROM (select 'Autoavaliação' AS `tipo`,`p`.`auto_avaliacao` AS `avaliacao`,case when `p`.`auto_avaliacao` = 'Proplayer' then 1 when `p`.`auto_avaliacao` = 'Avançado' then 2 when `p`.`auto_avaliacao` = 'Casual' then 3 when `p`.`auto_avaliacao` = 'Iniciante' then 4 when `p`.`auto_avaliacao` = 'Noob' then 5 end AS `ordem`,case when `p`.`auto_avaliacao` = 'Proplayer' then '80% a 100%' when `p`.`auto_avaliacao` = 'Avançado' then '60% a 79%' when `p`.`auto_avaliacao` = 'Casual' then '40% a 59%' when `p`.`auto_avaliacao` = 'Iniciante' then '20% a 39%' when `p`.`auto_avaliacao` = 'Noob' then '0% a 19%' end AS `faixa`,avg(`p`.`percentual_acertos`) AS `acerto` from `vw_apriori` `p` where `p`.`auto_avaliacao` not in ('Em processo','Não Preenchido','Meu nível para') group by `p`.`auto_avaliacao`,case when `p`.`auto_avaliacao` = 'Proplayer' then 1 when `p`.`auto_avaliacao` = 'Avançado' then 2 when `p`.`auto_avaliacao` = 'Casual' then 3 when `p`.`auto_avaliacao` = 'Iniciante' then 4 when `p`.`auto_avaliacao` = 'Noob' then 5 end order by `p`.`auto_avaliacao`) AS `t` ORDER BY `t`.`ordem` ASC ;

