--
-- Estrutura para view `vw_partidas`
--
DROP TABLE IF EXISTS `vw_partidas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_partidas`  AS WITH cte_extremos AS (SELECT `vw_desempenho`.`escola` AS `escola`, `vw_desempenho`.`turma` AS `turma`, `vw_desempenho`.`login` AS `login`, `vw_desempenho`.`jogador` AS `jogador`, `vw_desempenho`.`partida` AS `partida`, `vw_desempenho`.`dt_jogo` AS `dt_jogo`, `vw_desempenho`.`idade` AS `idade`, `vw_desempenho`.`auto_avaliacao` AS `auto_avaliacao`, `vw_desempenho`.`avaliacao_jogo` AS `avaliacao_jogo`, `vw_desempenho`.`tutor` AS `tutor`, `vw_desempenho`.`categoria` AS `categoria`, `vw_desempenho`.`tema` AS `tema`, `vw_desempenho`.`finalizada` AS `finalizada`, `vw_desempenho`.`numero_partidas` AS `numero_partidas`, `vw_desempenho`.`numero_perguntas` AS `numero_perguntas`, `vw_desempenho`.`tempo_gasto` AS `tempo_gasto`, `vw_desempenho`.`tempo_leitura_adulto` AS `tempo_leitura_adulto`, `vw_desempenho`.`tempo_leitura_infantil` AS `tempo_leitura_infantil`, `vw_desempenho`.`numero_acertos` AS `numero_acertos`, `vw_desempenho`.`numero_erros` AS `numero_erros`, `vw_desempenho`.`percentual_acertos` AS `percentual_acertos`, `vw_desempenho`.`percentual_erros` AS `percentual_erros`, min(`vw_desempenho`.`partida`) over ( partition by `vw_desempenho`.`escola`,`vw_desempenho`.`turma`,`vw_desempenho`.`login`,`vw_desempenho`.`jogador`) AS `primeira_id`, max(`vw_desempenho`.`partida`) over ( partition by `vw_desempenho`.`escola`,`vw_desempenho`.`turma`,`vw_desempenho`.`login`,`vw_desempenho`.`jogador`) AS `ultima_id` FROM `vw_desempenho`) SELECT `cte_extremos`.`escola` AS `escola`, `cte_extremos`.`turma` AS `turma`, `cte_extremos`.`login` AS `login`, `cte_extremos`.`jogador` AS `jogador`, `cte_extremos`.`partida` AS `partida`, `cte_extremos`.`dt_jogo` AS `dt_jogo`, `cte_extremos`.`idade` AS `idade`, `cte_extremos`.`auto_avaliacao` AS `auto_avaliacao`, `cte_extremos`.`avaliacao_jogo` AS `avaliacao_jogo`, `cte_extremos`.`tutor` AS `tutor`, `cte_extremos`.`categoria` AS `categoria`, `cte_extremos`.`tema` AS `tema`, `cte_extremos`.`numero_partidas` AS `numero_partidas`, `cte_extremos`.`tempo_gasto` AS `tempo_gasto`, `cte_extremos`.`tempo_leitura_adulto` AS `tempo_leitura_adulto`, `cte_extremos`.`tempo_leitura_infantil` AS `tempo_leitura_infantil`, `cte_extremos`.`percentual_acertos` AS `percentual_acertos`, `cte_extremos`.`percentual_erros` AS `percentual_erros`, `cte_extremos`.`finalizada` AS `finalizada`, CASE WHEN `cte_extremos`.`partida` = `cte_extremos`.`primeira_id` THEN 'PARTIDA INICIAL' WHEN `cte_extremos`.`partida` = `cte_extremos`.`ultima_id` THEN 'PARTIDA FINAL' ELSE 'PARTIDAS INTERMEDIÁRIAS' END AS `tipo_partida` FROM `cte_extremos``cte_extremos`  ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_perfil_turma`
--
DROP TABLE IF EXISTS `vw_perfil_turma`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_perfil_turma`  AS SELECT row_number() over ( order by `r`.`escola`,`r`.`turma`) AS `id`, `r`.`escola` AS `escola`, `r`.`turma` AS `turma`, count(distinct `r`.`jogador`) AS `total_alunos`, concat(convert(format(avg(distinct `r`.`idade`),2) using utf8mb4),' ± ',convert(format(std(`r`.`idade`),2) using utf8mb4)) AS `idade`, CASE WHEN `r`.`turma` = 'Turma A' THEN 'Rio de Janeiro (RJ - Brasil)' WHEN `r`.`turma` = 'Turma B' THEN 'Rio de Janeiro (RJ - Brasil)' WHEN `r`.`turma` = 'Turma C' THEN 'Foz do Iguaçu (PR - Brasil)' END AS `localizacao_geo` FROM `vw_analise_capacidade` AS `r` GROUP BY `r`.`escola`, `r`.`turma` ORDER BY `r`.`escola` ASC, `r`.`turma` ASC ;

