--
-- Estrutura para view `vw_respostas`
--
DROP TABLE IF EXISTS `vw_respostas`;

CREATE ALGORITHM=TEMPTABLE DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_respostas`  AS SELECT DISTINCT `vda`.`nome_escola` AS `escola`, `vda`.`identificacao_turma` AS `turma`, `vda`.`login_usuario` AS `login`, `vda`.`jogador_partida` AS `jogador`, `vda`.`id_partida` AS `partida`, `vda`.`dt_jogo_partida` AS `dt_jogo`, `vda`.`num_jogada_log_pergunta` AS `jogada`, `vda`.`idade_jogador_partida` AS `idade`, `vda`.`auto_avaliacao_partida` AS `auto_avaliacao`, `vda`.`avaliacao_jogo_partida` AS `avaliacao_jogo`, `vda`.`realizada_tutor_log_pergunta` AS `tutor`, `vda`.`id_pergunta` AS `pergunta_id`, `vda`.`categoria_pergunta` AS `categoria`, `vda`.`tema` AS `tema`, `vda`.`resp_certa_pergunta` AS `resposta_certa`, `vda`.`resp_dada_log_pergunta` AS `resposta_dada`, `vda`.`tempo_gasto_log_pergunta` AS `tempo_gasto`, `vda`.`tempo_leitura_adulto_pergunta` AS `tempo_leitura_adulto`, `vda`.`tempo_leitura_infantil_pergunta` AS `tempo_leitura_infantil`, CASE WHEN `vda`.`resp_certa_pergunta` = `vda`.`resp_dada_log_pergunta` THEN 1 ELSE 0 END AS `acerto`, CASE WHEN `vda`.`resp_certa_pergunta` <> `vda`.`resp_dada_log_pergunta` THEN 1 ELSE 0 END AS `erro`, `vda`.`partida_finalizada` AS `finalizada` FROM `vw_dados_analiticos` AS `vda` ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_resumo_partidas`
--
DROP TABLE IF EXISTS `vw_resumo_partidas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_resumo_partidas`  AS SELECT row_number() over () AS `id`, `t`.`escola` AS `escola`, `t`.`turma` AS `turma`, `t`.`caracteristicas_observadas` AS `caracteristicas_observadas`, `t`.`media` AS `media`, `t`.`desvio` AS `desvio`, `t`.`ordem` AS `ordem` FROM (select `r`.`escola` AS `escola`,`r`.`turma` AS `turma`,`r`.`caracteristicas_observadas` AS `caracteristicas_observadas`,`r`.`valor` AS `media`,`r`.`desvio` AS `desvio`,`r`.`ordem` AS `ordem` from `vw_tempo_resposta_media` `r` union all select `p`.`escola` AS `escola`,`p`.`turma` AS `turma`,`p`.`caracteristicas_observadas` AS `caracteristicas_observadas`,`p`.`valor` AS `media`,`p`.`desvio` AS `desvio`,`p`.`ordem` AS `ordem` from `vw_tempo_partida_media` `p` union all select `p`.`escola` AS `escola`,`p`.`turma` AS `turma`,'Percentual de Acertos por partida (%)' AS `caracteristicas_observadas`,avg(`p`.`percentual_acertos`) AS `media`,std(`p`.`percentual_acertos`) AS `desvio`,3 AS `ordem` from `vw_partidas` `p` group by `p`.`escola`,`p`.`turma`) AS `t` ;

