--
-- Estrutura para view `vw_tempo_partida_media`
--
DROP TABLE IF EXISTS `vw_tempo_partida_media`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `vw_tempo_partida_media`  AS WITH tempo_partida_media AS (SELECT `r`.`escola` AS `escola`, `r`.`turma` AS `turma`, 'Tempo de resposta por partida (segundos)' AS `caracteristicas_observadas`, avg(`r`.`tempo_gasto`) AS `valor` FROM `vw_partidas` AS `r` GROUP BY `r`.`escola`, `r`.`turma`), tempo_partida_media_filtrada AS (SELECT `m`.`escola` AS `escola`, `m`.`turma` AS `turma`, `m`.`caracteristicas_observadas` AS `caracteristicas_observadas`, `m`.`valor` AS `valor`, std(`r`.`tempo_gasto`) AS `desvio`, 2 AS `ordem` FROM (`vw_partidas` `r` join `tempo_partida_media` `m` on(`r`.`escola` = `m`.`escola` and `r`.`turma` = `m`.`turma`)) WHERE `r`.`tempo_gasto` between `m`.`valor` * 0.10 and `m`.`valor` * 1.90 GROUP BY `r`.`escola`, `r`.`turma`)  SELECT `m`.`escola` AS `escola`, `m`.`turma` AS `turma`, `m`.`caracteristicas_observadas` AS `caracteristicas_observadas`, `m`.`valor` AS `valor`, `m`.`desvio` AS `desvio`, `m`.`ordem` AS `ordem` FROM `tempo_partida_media_filtrada` AS `m` GROUP BY `m`.`escola`, `m`.`turma` ORDER BY `m`.`turma` ASC`turma`  ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_tempo_resposta_media`
